<style>
.ac-page{font-family:Inter,system-ui,sans-serif;color:#25313c}.ac-head{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;margin-bottom:20px}.ac-head h1{margin:0 0 5px;color:#123b5d;font-size:23px;font-weight:750}.ac-sub{font-size:13px;color:#64748b}.ac-actions{display:flex;gap:9px;flex-wrap:wrap}.ac-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 15px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;color:#123b5d;text-decoration:none;font-size:13px;font-weight:650;cursor:pointer}.ac-btn.primary{background:#123b5d;border-color:#123b5d;color:#fff}.ac-nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.ac-nav a{padding:8px 11px;border:1px solid #dbe3ec;border-radius:8px;color:#34536b;text-decoration:none;font-size:12px}.ac-panel,.ac-kpi{background:#fff;border:1px solid #dbe3ec;border-radius:14px;padding:18px;margin-bottom:16px}.ac-panel h3{margin:0 0 14px;color:#123b5d;font-size:15px}.ac-kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:16px}.ac-kpi{margin:0}.ac-kpi span{font-size:12px;color:#64748b}.ac-kpi strong{display:block;margin-top:8px;font-size:25px;color:#123b5d}.ac-table{width:100%;border-collapse:collapse;font-size:12px}.ac-table th{background:#f8fafc;color:#64748b;font-size:11px;text-align:left;padding:12px 9px}.ac-table td{padding:12px 9px;border-bottom:1px solid #e2e8f0}.ac-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.ac-field label{display:block;margin-bottom:6px;font-size:12px;font-weight:650;color:#475569}.ac-field input,.ac-field select,.ac-field textarea{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;font:13px Inter,sans-serif}.ac-field textarea{min-height:100px}.ac-badge{display:inline-block;border-radius:20px;padding:4px 9px;font-size:11px;font-weight:700;background:#eef2f7;color:#475569}.ac-badge.pending{background:#fff4d6;color:#9a6700}.ac-badge.approved{background:#e8f7ee;color:#16803c}.ac-badge.rejected{background:#feecec;color:#b42318}.ac-badge.returned{background:#fff0e0;color:#a34d00}.ac-flow{display:flex;align-items:center;gap:10px;overflow:auto;padding:20px 4px}.ac-node{min-width:155px;padding:15px;border:1px solid #cbd5e1;border-radius:12px;background:white;text-align:center;position:relative}.ac-node small{display:block;color:#64748b;margin-top:5px}.ac-node.done{border-color:#16a34a;background:#f0fdf4}.ac-node.active{border:2px solid #d97706;box-shadow:0 0 0 4px #fef3c7;animation:acPulse 1.8s infinite}.ac-node.wait{opacity:.7}.ac-arrow{min-width:42px;height:2px;background:#94a3b8;position:relative}.ac-arrow:after{content:'';position:absolute;right:0;top:-4px;border-left:8px solid #94a3b8;border-top:5px solid transparent;border-bottom:5px solid transparent}.ac-arrow.done{background:#16a34a;background-image:linear-gradient(90deg,#16a34a 50%,transparent 50%);background-size:14px 2px;animation:acFlow 1s linear infinite}.ac-arrow.done:after{border-left-color:#16a34a}@keyframes acFlow{to{background-position:14px 0}}@keyframes acPulse{50%{box-shadow:0 0 0 7px #fef3c7}}.ac-timeline{border-left:2px solid #dbe3ec;margin-left:8px;padding-left:20px}.ac-event{position:relative;margin:0 0 18px}.ac-event:before{content:'';position:absolute;left:-27px;top:4px;width:10px;height:10px;border-radius:50%;background:#176b87;border:3px solid #eaf4f9}.ac-muted{font-size:12px;color:#64748b}@media(max-width:1000px){.ac-kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.ac-head{flex-direction:column}.ac-form{grid-template-columns:1fr}}
</style>
